package com.payshield.service;
import com.payshield.api.PaymentRequest; import com.payshield.domain.*; import com.payshield.repo.*; import org.junit.jupiter.api.*; import org.mockito.*; import java.math.BigDecimal; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
class PaymentServiceTest { @Mock PaymentRepository payments; @Mock IdempotencyRepository keys; @Mock PaymentTransitionRepository transitions; @Mock LedgerRepository ledger; @Mock OutboxRepository outbox; PaymentService service; PaymentRequest ok=new PaymentRequest(new BigDecimal("100.00"),"INR","order-1","cust-1","tok_visa_success"); @BeforeEach void setUp(){MockitoAnnotations.openMocks(this);when(keys.lockByKey(any())).thenReturn(Optional.empty());when(keys.saveAndFlush(any())).thenAnswer(i->i.getArgument(0));service=new PaymentService(payments,keys,transitions,ledger,outbox,new MockGateway());} @Test void createsSuccessfulPaymentAndLedger(){var r=service.create(ok,"key-1");assertEquals("SUCCEEDED",r.status());verify(ledger,times(2)).save(any());verify(outbox).save(any());} @Test void declineIsPersisted(){var r=service.create(new PaymentRequest(new BigDecimal("1"),"USD","a","b","tok_declined"),"key-2");assertEquals("FAILED",r.status());assertNotNull(r.failureReason());} @Test void rejectsMissingKey(){var e=assertThrows(PaymentException.class,()->service.create(ok,null));assertEquals(400,e.status());} @Test void rejectsKeyPayloadMismatch(){IdempotencyRecord record=new IdempotencyRecord("key-3","wrong","PAYMENT");when(keys.lockByKey("key-3")).thenReturn(Optional.of(record));var e=assertThrows(PaymentException.class,()->service.create(ok,"key-3"));assertEquals(409,e.status());}}
